		const char *names[5]={"LOW","MEDIUM","DEFAULT","QUALITY","MAX"}; const float scales[5]={0.5f,0.75f,1,1.5f,2};
		for(int i=0;i<5;++i){ const float bx=-0.66f+i*0.27f; buttonAt(names[i],bx,ys[2]-0.004f,0.24f,i==ms.resolutionPreset,true); unsigned w=0,h=0; char size[24]; if(VRMenu::CalculateResolutionForScale(scales[i],&w,&h))sprintf_s(size,"%uX%u",w,h);else sprintf_s(size,"UNKNOWN"); text(size,bx+0.016f,ys[2]-0.048f,0.0038f,0.58f,0.60f,0.64f); }
