		VRPose::GetCurrentLeftHandMenuAdjust(leftPosition,leftRotation);
		for(int i=0;i<6;++i){ row(-0.78f,ys[i],-0.02f,0.052f); const float v=i<3?weaponPosition[i]:weaponRotation[i-3]; sliderAt(axis[i],-0.72f,ys[i],0.62f,v,i<3?-1.0f:-180.0f,i<3?1.0f:180.0f,weaponReady); }
		row(-0.78f,-0.33f,-0.02f,0.040f); buttonAt("APPLY WEAPON",-0.58f,-0.33f,0.38f,false,weaponReady);
		for(int i=0;i<6;++i){ row(0.02f,ys[i],0.78f,0.052f); const float v=i<3?leftPosition[i]:leftRotation[i-3]; sliderAt(axis[i],0.08f,ys[i],0.62f,v,i<3?-0.75f:-85.0f,i<3?0.75f:85.0f,true); }
		row(0.02f,-0.33f,0.78f,0.040f); buttonAt("APPLY LEFT HAND",0.17f,-0.33f,0.46f,false,true);
